-- BRUVIFIT / MySQL 8 / execução MANUAL fora do Flyway.
-- Lote aplicado no desenvolvimento local em 26/11/2026 após backup e validação.
-- Flags abaixo continuam desabilitadas por padrão; lote BFCAT26 é idempotente.
-- Não executar contra produção. Confirme host local, schema e backup primeiro.
-- Abra em conexão localhost/127.0.0.1 no Workbench e selecione schema bruvifit.
SET NAMES utf8mb4;
SET SESSION time_zone='-03:00';
SELECT DATABASE() banco,@@hostname servidor,@@port porta,VERSION() versao;
-- ETAPA 1: execute e exporte este resultado como backup CSV/JSON (todos os campos).
-- Preserve o arquivo exportado antes de habilitar qualquer escrita.
SELECT * FROM produto WHERE categoria IS NULL OR TRIM(categoria)=''
 OR BINARY categoria NOT IN (BINARY 'Camisetas',BINARY 'Calças',BINARY 'Acessórios');
-- Fontes oficiais: ProdutoRequest.CATEGORIAS_VALIDAS e validação do cadastro.
-- Revisão dos registros do SQL inicial: somente camiseta e calça são inequívocas.
-- TESTE-PROD-003 (tênis) e TESTE-PROD-004 (moletom) ficam PENDENTES: não inventar categoria.
SET @confirm_local_development=0;
SET @backup_exportado=0;
-- Opcional: enriquecer com 3 novos SKUs, 3 clientes, 60 pedidos, 180 itens,
-- 60 recebimentos e 183 movimentos. Todos os novos pedidos são de AGORA.
-- Não retrodatamos vendas de novos produtos/clientes; por isso esse lote não
-- preenche artificialmente 7/28/90 dias completos. Histórico existente é preservado.
SET @inserir_exemplos=0;
START TRANSACTION;
SET @write_ok=(@confirm_local_development=1 AND @backup_exportado=1 AND DATABASE()='bruvifit'
 AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND ENGINE='InnoDB'
 AND table_name IN ('produto','pedido','item_pedido','estoque','financeiro','cliente'))=6
 AND NOT EXISTS(SELECT 1 FROM information_schema.triggers WHERE trigger_schema=DATABASE()
 AND event_object_table IN ('produto','pedido','item_pedido','estoque','financeiro','cliente')));
-- Bloqueie os registros afetados e registre os valores ANTES (exportar este resultado).
SELECT id,sku,nome,categoria FROM produto WHERE categoria IS NULL OR TRIM(categoria)=''
 OR BINARY categoria NOT IN (BINARY 'Camisetas',BINARY 'Calças',BINARY 'Acessórios') FOR UPDATE;
SET @sem_antes=(SELECT COUNT(*) FROM produto WHERE categoria IS NULL OR TRIM(categoria)=''
 OR BINARY categoria NOT IN (BINARY 'Camisetas',BINARY 'Calças',BINARY 'Acessórios'));
-- Apenas categorias existentes que correspondem semanticamente às oficiais
-- (espaços, capitalização e acentuação) ou dois SKUs/nome conhecidos e revisados.
UPDATE produto SET categoria=CASE
 WHEN CONVERT(TRIM(categoria) USING utf8mb4) COLLATE utf8mb4_0900_ai_ci='Camisetas' THEN 'Camisetas'
 WHEN CONVERT(TRIM(categoria) USING utf8mb4) COLLATE utf8mb4_0900_ai_ci='Calças' THEN 'Calças'
 WHEN CONVERT(TRIM(categoria) USING utf8mb4) COLLATE utf8mb4_0900_ai_ci='Acessórios' THEN 'Acessórios'
 WHEN sku='TESTE-PROD-001' AND nome='Camiseta Teste Normal' THEN 'Camisetas'
 WHEN sku='TESTE-PROD-002' AND nome='Calca Teste Estoque Baixo' THEN 'Calças'
 ELSE categoria END
WHERE @write_ok=1
 AND (categoria IS NULL OR TRIM(categoria)='' OR BINARY categoria NOT IN (BINARY 'Camisetas',BINARY 'Calças',BINARY 'Acessórios'))
 AND (CONVERT(TRIM(categoria) USING utf8mb4) COLLATE utf8mb4_0900_ai_ci IN ('Camisetas','Calças','Acessórios')
 OR (sku='TESTE-PROD-001' AND nome='Camiseta Teste Normal')
 OR (sku='TESTE-PROD-002' AND nome='Calca Teste Estoque Baixo'));
SET @corrigidos=ROW_COUNT();
SELECT @write_ok escrita_habilitada,@sem_antes ausentes_invalidos_antes,@corrigidos produtos_corrigidos;
-- Enriquecimento opcional: não altera estoque ou outros campos dos produtos existentes.
SET @actor=(SELECT MIN(id) FROM usuario WHERE ativo=1 AND aprovado=1);
SET @enrich_ok=(@write_ok=1 AND @inserir_exemplos=1 AND @actor IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM produto WHERE sku LIKE 'BFCAT26-%')
 AND NOT EXISTS(SELECT 1 FROM cliente WHERE email LIKE 'bfcat26.%@example.invalid')
 AND NOT EXISTS(SELECT 1 FROM pedido WHERE chave_requisicao LIKE 'BFCAT26-%'));

SET @c0=(SELECT id FROM cliente WHERE email='bfcat26.0@example.invalid');
SET @c1=(SELECT id FROM cliente WHERE email='bfcat26.1@example.invalid');
SET @c2=(SELECT id FROM cliente WHERE email='bfcat26.2@example.invalid');
SET @p0=(SELECT id FROM produto WHERE sku='BFCAT26-0');
SET @p1=(SELECT id FROM produto WHERE sku='BFCAT26-1');
SET @p2=(SELECT id FROM produto WHERE sku='BFCAT26-2');
