-- Diagnóstico APÓS: sem correções arbitrárias para os produtos pendentes.
SELECT id,sku,nome,categoria FROM produto WHERE categoria IS NULL OR TRIM(categoria)=''
 OR BINARY categoria NOT IN (BINARY 'Camisetas',BINARY 'Calças',BINARY 'Acessórios');
SELECT categoria,COUNT(*) produtos FROM produto GROUP BY categoria;
SELECT @sem_antes antes,@corrigidos corrigidos,
 (SELECT COUNT(*) FROM produto WHERE categoria IS NULL OR TRIM(categoria)=''
 OR BINARY categoria NOT IN (BINARY 'Camisetas',BINARY 'Calças',BINARY 'Acessórios')) depois;
SELECT COUNT(*) novos_produtos FROM produto WHERE sku LIKE 'BFCAT26-%';
SELECT COUNT(*) novos_pedidos FROM pedido WHERE chave_requisicao LIKE 'BFCAT26-%';
-- Comparar esta distribuição com categories/count/percentage e totalUnits da API.
-- Todo o período inclui hoje. Para 7/28/90, substituir @inicio/@fim pelas datas
-- retornadas pela API: primeiro dia inclusivo e dia seguinte ao último exclusivo.
SET @inicio=NULL; SET @fim=NOW(); SET @categoria=NULL; SET @pagamento=NULL;
SELECT COALESCE(p.categoria,'Sem categoria') categoria,SUM(i.quantidade) unidades,
 ROUND(100*SUM(i.quantidade)/SUM(SUM(i.quantidade)) OVER(),1) percentual,
 SUM(SUM(i.quantidade)) OVER() total_unidades
FROM pedido pe JOIN item_pedido i ON i.pedido_id=pe.id JOIN produto p ON p.id=i.produto_id
WHERE UPPER(TRIM(pe.status)) IN ('CONCLUIDO','CONCLUÍDO','ENTREGUE','FINALIZADO')
 AND (@inicio IS NULL OR pe.data_pedido>=@inicio) AND pe.data_pedido<@fim
 AND (@categoria IS NULL OR p.categoria=@categoria) AND (@pagamento IS NULL OR pe.forma_pagamento=@pagamento)
GROUP BY p.categoria;
-- Devem retornar ZERO linhas: divergências de total e de saldo.
SELECT pe.id FROM pedido pe JOIN item_pedido i ON i.pedido_id=pe.id
WHERE pe.chave_requisicao LIKE 'BFCAT26-%' GROUP BY pe.id,pe.valor_total HAVING SUM(i.subtotal)<>pe.valor_total;
SELECT p.id FROM produto p JOIN estoque e ON e.produto_id=p.id WHERE p.sku LIKE 'BFCAT26-%'
GROUP BY p.id,p.saldo_estoque HAVING SUM(CASE WHEN e.tipo='ENTRADA' THEN e.quantidade ELSE -e.quantidade END)<>p.saldo_estoque;
